call = re.compile(r'\b(?:devm_)?request(?:_threaded|_any|_percpu|_noprobe|_pirq)?_irq(?:_exclusive|_arrays|_resources|_free)?\s*\(')

def read(fp):
    return open(fp, encoding='utf-8', errors='replace').read()

# 1) direct handler functions, keyed by registering file AND global map
file_handlers = {}   # relfile -> set of handler names
global_handlers = {} # name -> first registering relfile

def resolve_handlers(text):
    hs = set()
    for m in call.finditer(text):
        i = m.end()
        depth = 0
        j = i
        while j < len(text):
            if text[j] == '(':
                depth += 1
            elif text[j] == ')':
                if depth == 0:
                    break
                depth -= 1
            elif text[j] == ';' or text[j] == '\n':
                # request_irq style: allow newline inside args; stop at ';' only at depth 0
                if text[j] == ';' and depth == 0:
                    break
            j += 1
        args = text[i:j]
        # split args at depth-0 commas
        parts, buf, d = [], [], 0
        for ch in args:
            if ch in '([': d += 1
            if ch in ')]': d -= 1
            if ch == ',' and d == 0:
                parts.append(''.join(buf)); buf = []
            else:
                buf.append(ch)
        parts.append(''.join(buf))
        if len(parts) >= 2:
            h = parts[1].strip()
            h = re.sub(r'^(?:\([a-zA-Z_][\w\s\*]*\)\s*)?', '', h)  # cast
            h = h.split('=')[0].strip()
            nm = re.match(r'^[A-Za-z_]\w*', h)
            if nm: hs.add(nm.group(0))
    return hs

files = []
for dp, _, fs in os.walk(Tree):
    for f in fs:
        if f.endswith(('.c', '.h')):
            files.append(os.path.join(dp, f))

pref = ('drivers/', 'sound/', 'net/', 'fs/', 'kernel/', 'block/', 'crypto/', 'arch/', 'lib/')
for fp in files:
    rel = os.path.relpath(fp, Tree)
    if not rel.startswith(pref): continue
    src = read(fp)
    hs = resolve_handlers(src)
    if hs:
        file_handlers[rel] = hs
        for h in hs:
            global_handlers.setdefault(h, rel)

# 2) resolve handler definition files & check body for plain spin_lock
plain = re.compile(r'\bspin_lock\s*\(')
defn_re = re.compile(r'\b(?:static\s+)?(?:irqreturn_t\s+|void\s+|int\s+|enum\s+irqreturn\s+)?([A-Za-z_]\w*)\s*\(')

handler_def = {}  # name -> (relfile, startline)
for fp in files:
    src = read(fp)
    lines = src.split('\n')
    for idx, ln in enumerate(lines):
        for h in global_handlers:
            if h in handler_def: continue
            m = re.search(r'\b' + re.escape(h) + r'\s*\(', ln)
