        depth += lines[k].count('{') - lines[k].count('}')
        if '{' in lines[k]:
            started = True
        if started and depth <= 0:
            break
        k += 1
    btext = '\n'.join(body)
    if plain.search(btext):
        results.append((rel, ln, h))

with open(os.path.join(T, 'handlers_plain.txt'), 'w') as f:
    for rel, ln, h in sorted(results):
        f.write(f'{rel}:{ln}\t{h}\n')
print(f'global handlers: {len(global_handlers)}, resolved defs: {len(handler_def)}, handlers w/ plain spin_lock: {len(results)}')
EOF
