                # gather handler token: for request_irq(f, h, ...) h is 2nd arg
                # for request_threaded_irq(f, h1, h2, ...) h1 is 2nd, h2 is 3rd
                # crude: take identifiers on this line and next lines until ');'
                blob = ln
